def topological_sort(graph):
    visited = set()
    in_progress = set()
    order = []

    def visit(node):
        if node in in_progress:
            raise ValueError('cycle detected')
        if node in visited:
            return
        in_progress.add(node)
        for dependency in graph.get(node, []):
            visit(dependency)
        in_progress.remove(node)
        visited.add(node)
        order.append(node)

    for node in graph:
        visit(node)
    return order
```

